<?php
namespace App\Models; use Illuminate\Foundation\Auth\User as Authenticatable; use Illuminate\Notifications\Notifiable; use Illuminate\Database\Eloquent\Relations\BelongsTo;
class User extends Authenticatable {use Notifiable; protected $fillable=['name','email','password','role','google_id','company_id']; protected $hidden=['password','remember_token']; protected function casts():array{return ['email_verified_at'=>'datetime','password'=>'hashed'];} public function company():BelongsTo{return $this->belongsTo(Company::class);} public function isStaff():bool{return in_array($this->role,['admin','petugas']);} }
